#!/usr/bin/env node
/**
 * Builds figma-plugin/code.js from figma-plugin/kit.json and the sources in figma-plugin/src/.
 * Figma plugins can't read files, so the kit data is embedded. --check fails if code.js is stale.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';

const dir = join(dirname(new URL(import.meta.url).pathname), '..', 'figma-plugin');
const kit = JSON.parse(readFileSync(join(dir, 'kit.json'), 'utf-8'));
const out = [
  '/* Generated by scripts/build-figma-plugin.mjs from kit.json and src/. Do not edit by hand. */',
  'const KIT = ' + JSON.stringify(kit) + ';',
  readFileSync(join(dir, 'src', 'kit-builder.js'), 'utf-8'),
  readFileSync(join(dir, 'src', 'plugin.js'), 'utf-8'),
].join('\n');
const target = join(dir, 'code.js');
if (process.argv.includes('--check')) {
  let current = '';
  try { current = readFileSync(target, 'utf-8'); } catch { /* missing counts as stale */ }
  if (current !== out) { console.error('FAIL: figma-plugin/code.js is out of date. Run: npm run build:figma-plugin'); process.exit(1); }
  console.log('figma-plugin/code.js is up to date.');
} else {
  writeFileSync(target, out);
  console.log(`Wrote ${target} (${kit.components.length} components, ${out.length} bytes).`);
}
